mapper.update:
UPDATE funding_backfill_request
SET state = 'IDLE', current_run_id = NULL
WHERE id = #{id} AND state = 'RUNNING' AND current_run_id = #{runId}

UPDATE funding_backfill_request
SET cursor_ts = #{cursor}, pages_fetched = pages_fetched + 1,
    earliest_fact_time = #{earliest}, latest_fact_time = #{latest}
WHERE id = #{id} AND state = 'RUNNING' AND current_run_id = #{runId}

UPDATE funding_backfill_request
SET state = #{state}, coverage_state = #{coverage}, current_run_id = NULL
WHERE id = #{id} AND state = 'RUNNING' AND current_run_id = #{runId}
